<div class="col-md-6 mb-3"><label>Admission Session *</label><select id="admission-session" class="form-control" name="admission_session_id" required><?php foreach($sessionItems as $s): ?><option value="<?= $s->id ?>" <?= (string)$v('admission_session_id')===(string)$s->id?'selected':'' ?>><?= esc($s->title) ?></option><?php endforeach ?></select></div>
