<div class="col-md-6 mb-3"><label>Shift</label><select id="admission-shift" class="form-control" name="shift_id"><option value="">All / none</option><?php foreach($academic['shifts'] as $s): ?><option value="<?= $s->id ?>" <?= (string)$v('shift_id')===(string)$s->id?'selected':'' ?>><?= esc($s->title) ?></option><?php endforeach ?></select></div>
<div class="col-md-3 mb-3"><label>Available Seats *</label><input type="number" min="0" class="form-control" name="available_seats" value="<?= esc($v('available_seats',0)) ?>" required></div>
<div class="col-md-3 mb-3"><label>Minimum Age</label><input type="number" min="0" step="0.1" class="form-control" name="minimum_age" value="<?= esc($v('minimum_age')) ?>"></div>
<div class="col-md-3 mb-3"><label>Maximum Age</label><input type="number" min="0" step="0.1" class="form-control" name="maximum_age" value="<?= esc($v('maximum_age')) ?>"></div>
