<?php foreach(['application_start'=>'Application Start *','application_deadline'=>'Application Deadline *'] as $key=>$label): ?><div class="col-md-6 mb-3"><label><?= $label ?></label><input type="datetime-local" class="form-control" name="<?= $key ?>" value="<?= esc($v($key)?date('Y-m-d\TH:i',strtotime($v($key))):'') ?>" required></div><?php endforeach ?>
<div class="col-md-6 mb-3"><label>Application Fee</label><input type="number" min="0" step="0.01" class="form-control" name="application_fee" value="<?= esc($v('application_fee',0)) ?>"></div><div class="col-md-6 mb-3"><label>Admission Fee</label><input type="number" min="0" step="0.01" class="form-control" name="admission_fee" value="<?= esc($v('admission_fee',0)) ?>"></div>
