<script>document.getElementById('admission-school').addEventListener('change',async function(){const d=await fetch('<?= base_url('school/admission/academic-data') ?>/'+this.value).then(r=>r.json());const fill=(id,rows,blank='')=>document.getElementById(id).innerHTML=blank+rows.map(x=>`<option value="${x.id}">${x.title}</option>`).join('');fill('admission-session',d.sessions);fill('admission-class',d.classes);fill('admission-shift',d.shifts,'<option value="">All / none</option>');});</script>
